if (msgType !== "POST_TELEMETRY_REQUEST") {
    return {msg: msg, metadata: metadata, msgType: "IGNORED"};
}
var ZONE_MAP = {
    "765ca3077000": "room_1",
    "125ba3077000": "room_2",
    "22458bdf948c": "room_3"
};
var ZONE_NUM_MAP = {
    "out_of_range": 0, "room_1": 1, "room_2": 2, "room_3": 3
};
var scannerId = msg.scanner_id;
var rssi = msg.rssi;
if (!scannerId || rssi === undefined || rssi === null) {
    return {msg: {error: "missing scanner_id or rssi"}, metadata: metadata, msgType: "INVALID"};
}
var zone = ZONE_MAP[scannerId] || "out_of_range";
msg.zone = zone;
msg.scanner_id = scannerId;
msg.rssi = rssi;
msg.zone_num = ZONE_NUM_MAP[zone];
return {msg: msg, metadata: metadata, msgType: msgType};

var HYSTERESIS_DBM = 5;
var DEBOUNCE_COUNT = 2;
var SCANNER_VALID_MS = 10000;
var ZONE_MAP = {
    "765ca3077000": "room_1",
    "125ba3077000": "room_2",
    "22458bdf948c": "room_3"
};
var ZONE_NUM_MAP = {
    "out_of_range": 0, "room_1": 1, "room_2": 2, "room_3": 3
};
var SCANNERS = ["765ca3077000", "125ba3077000", "22458bdf948c"];
// [FIX] SCANNERS[i] tuong ung ket qua luu ve theo VI TRI trong "Build attrs
// payload" (rssi_scan_01 = SCANNERS[0], v.v.) va duoc "Fetch tag state"
// fetch dung cac ten nay -- KHONG phai theo MAC. Truoc day tra getMeta("rssi_"
// + s) voi s la chuoi MAC (VD "rssi_765ca3077000"), khong bao gio khop voi
// key thuc te trong metadata -> snapshot RSSI cua 3 scanner khac (ngoai
// scanner vua gui message nay) luon undefined, hysteresis chi so sanh voi
// chinh scanner hien tai thay vi so sanh ca 4 nhu thiet ke.
var SCAN_RSSI_KEYS = ["rssi_scan_01", "rssi_scan_02", "rssi_scan_03"];
var SCAN_TS_KEYS = ["ts_scan_01", "ts_scan_02", "ts_scan_03"];
var now = Date.now();

// [FIX] Khong chac chan TB dung tien to gi cho metadata cua server-scope
// attribute fetch (ss_ / khong tien to / shared_...) -- thu lan luot nhieu
// kieu ten, dung gia tri dau tien tim thay, tranh phu thuoc doan sai 1 quy uoc.
function getMeta(baseName) {
    var candidates = ["ss_" + baseName, baseName, "shared_" + baseName, "cs_" + baseName];
    for (var i = 0; i < candidates.length; i++) {
        if (metadata[candidates[i]] !== undefined && metadata[candidates[i]] !== null) {
            return metadata[candidates[i]];
        }
    }
    return undefined;
}

var newScannerId = msg.scanner_id;
var newRssi = parseInt(msg.rssi);
var snap = {};
for (var i = 0; i < SCANNERS.length; i++) {
    var s = SCANNERS[i];
    var rVal = getMeta(SCAN_RSSI_KEYS[i]);
    var tVal = getMeta(SCAN_TS_KEYS[i]);
    if (rVal !== undefined && tVal !== undefined) {
        snap[s] = { rssi: parseInt(rVal), ts: parseInt(tVal) };
    }
}
snap[newScannerId] = { rssi: newRssi, ts: now };

var bestScanner = null;
var bestRssi = -999;
for (var j = 0; j < SCANNERS.length; j++) {
    var sc = SCANNERS[j];
    if (snap[sc] && (now - snap[sc].ts) <= SCANNER_VALID_MS) {
        if (snap[sc].rssi > bestRssi) { bestRssi = snap[sc].rssi; bestScanner = sc; }
    }
}

var curZone = getMeta("current_zone");
var candZone = getMeta("candidate_zone");
var candCountRaw = getMeta("candidate_count");
var candCount = (candCountRaw !== undefined) ? parseInt(candCountRaw) : 0;

var finalZone, finalRssi, finalScanner;
var newCandZone = candZone;
var newCandCount = candCount;

if (!bestScanner) {
    // Khong scanner nao con "tuoi" trong SCANNER_VALID_MS -- mat dau that su, khong debounce
    finalZone = "out_of_range"; finalRssi = -999; finalScanner = "";
    newCandZone = "out_of_range"; newCandCount = 0;
} else {
    var bestZone = ZONE_MAP[bestScanner] || "out_of_range";

    if (!curZone || curZone === "out_of_range") {
        // Lan dau gan zone (hoac vua het out_of_range) -- khong can debounce
        finalZone = bestZone; finalRssi = bestRssi; finalScanner = bestScanner;
        newCandZone = bestZone; newCandCount = 0;
    } else if (bestZone === curZone) {
        // Dang o dung zone hien tai -- on dinh, reset candidate
        finalZone = curZone; finalRssi = bestRssi; finalScanner = bestScanner;
        newCandZone = curZone; newCandCount = 0;
    } else {
        // bestZone khac curZone -- kiem tra nguong hysteresis dBm truoc
        // [FIX] Mot phong co the co NHIEU scanner (VD room_1 rong, gan them
        // scanner phu tro) -- phai lay scanner TOT NHAT (RSSI cao nhat) trong
        // so cac scanner con "tuoi" thuoc curZone, khong chi lay scanner DAU
        // TIEN khop trong SCANNERS nhu truoc (se bo qua scanner phu cung phong
        // neu no dung truoc trong mang SCANNERS).
        var curZoneRssi = -999;
        var curZoneBestScanner = null;
        for (var k = 0; k < SCANNERS.length; k++) {
            var scK = SCANNERS[k];
            if (ZONE_MAP[scK] === curZone && snap[scK] && (now - snap[scK].ts) <= SCANNER_VALID_MS) {
                if (snap[scK].rssi > curZoneRssi) { curZoneRssi = snap[scK].rssi; curZoneBestScanner = scK; }
            }
        }
        var curZoneFresh = (curZoneBestScanner !== null);
        var prevCurrentRssiRaw = getMeta("current_rssi");
        var prevCurrentRssi = (prevCurrentRssiRaw !== undefined && prevCurrentRssiRaw !== null)
            ? parseInt(prevCurrentRssiRaw) : -999;
        var prevCurrentScanner = getMeta("current_scanner") || "";

        // A stale scanner must not vote in the hysteresis comparison. Keep its
        // last value only for display while debounce waits for confirmation.
        if (!curZoneFresh) {
            curZoneRssi = -999;
        }

        var passHysteresis = !curZoneFresh ||
            ((bestRssi - curZoneRssi) >= HYSTERESIS_DBM);
        if (passHysteresis) {
            // Vuot nguong dBm -- tich luy debounce, chua doi ngay
            if (bestZone === candZone) {
                newCandCount = candCount + 1;
            } else {
                newCandZone = bestZone;
                newCandCount = 1;
            }
            if (newCandCount >= DEBOUNCE_COUNT) {
                // Du so lan xac nhan lien tiep -- thuc su doi zone
                finalZone = bestZone; finalRssi = bestRssi; finalScanner = bestScanner;
                newCandZone = bestZone; newCandCount = 0;
            } else {
                // Chua du xac nhan -- giu nguyen zone cu, cho them report
                finalZone = curZone; finalRssi = curZoneFresh ? curZoneRssi : prevCurrentRssi; finalScanner = curZoneFresh ? curZoneBestScanner : prevCurrentScanner;
            }
        } else {
            // [FIX] Chua du nguong dBm o LAN NAY -- KHONG reset ve 0 het tien
            // do (qua khat khe voi nhieu RF), chi giam 1 kieu "leaky bucket".
            // Van giu nguyen candZone (xu huong) neu con dang duong, chi that
            // su ve lai curZone khi count giam het ve 0.
            finalZone = curZone; finalRssi = curZoneFresh ? curZoneRssi : prevCurrentRssi; finalScanner = curZoneFresh ? curZoneBestScanner : prevCurrentScanner;
            if (candZone && candZone !== curZone && candCount > 0) {
                newCandCount = candCount - 1;
                newCandZone = (newCandCount > 0) ? candZone : curZone;
            } else {
                newCandZone = curZone; newCandCount = 0;
            }
        }
    }
}

msg.current_zone = finalZone;
msg.current_rssi = finalRssi;
msg.current_scanner = finalScanner;
msg.current_zone_num = ZONE_NUM_MAP[finalZone];
msg.last_seen = now;
msg.candidate_zone = newCandZone;
msg.candidate_count = newCandCount;
msg.rssi_scan_01 = snap[SCANNERS[0]] ? snap[SCANNERS[0]].rssi : null;
msg.rssi_scan_02 = snap[SCANNERS[1]] ? snap[SCANNERS[1]].rssi : null;
msg.rssi_scan_03 = snap[SCANNERS[2]] ? snap[SCANNERS[2]].rssi : null;
msg.ts_scan_01 = snap[SCANNERS[0]] ? snap[SCANNERS[0]].ts : null;
msg.ts_scan_02 = snap[SCANNERS[1]] ? snap[SCANNERS[1]].ts : null;
msg.ts_scan_03 = snap[SCANNERS[2]] ? snap[SCANNERS[2]].ts : null;
return {msg: msg, metadata: metadata, msgType: msgType};

var ROOM_LABEL_MAP = {
    "out_of_range": "Out of Range",
    "room_1": "Room 1 (Bedroom 1)",
    "room_2": "Room 2 (Bedroom 2)",
    "room_3": "Room 3 (WC)"
};
var attrsPayload = {
    role: "tag",
    current_zone: msg.current_zone,
    current_zone_label: ROOM_LABEL_MAP[msg.current_zone] || msg.current_zone,
    current_rssi: msg.current_rssi,
    current_scanner: msg.current_scanner,
    last_seen: msg.last_seen,
    candidate_zone: msg.candidate_zone,
    candidate_count: msg.candidate_count
};
if (msg.battery !== undefined && msg.battery !== null) { attrsPayload.battery = msg.battery; }
if (msg.rssi_scan_01 !== null) { attrsPayload.rssi_scan_01 = msg.rssi_scan_01; attrsPayload.ts_scan_01 = msg.ts_scan_01; }
if (msg.rssi_scan_02 !== null) { attrsPayload.rssi_scan_02 = msg.rssi_scan_02; attrsPayload.ts_scan_02 = msg.ts_scan_02; }
if (msg.rssi_scan_03 !== null) { attrsPayload.rssi_scan_03 = msg.rssi_scan_03; attrsPayload.ts_scan_03 = msg.ts_scan_03; }
return {msg: attrsPayload, metadata: metadata, msgType: "POST_ATTRIBUTES_REQUEST"};

var ZONE_NUM_MAP = {
    "out_of_range": 0, "room_1": 1, "room_2": 2, "room_3": 3
};
var SCANNER_NUM_MAP = {
    "765ca3077000": 1,
    "125ba3077000": 2,
    "22458bdf948c": 3
};
var now = Date.now();
function ageSeconds(ts) {
    if (ts === undefined || ts === null) { return -1; }
    return Math.max(0, (now - parseInt(ts)) / 1000.0);
}
var tsPayload = {
    current_zone_num: msg.current_zone_num,
    current_rssi: msg.current_rssi,
    rssi_scan_01: msg.rssi_scan_01,
    rssi_scan_02: msg.rssi_scan_02,
    rssi_scan_03: msg.rssi_scan_03,
    candidate_zone_num: ZONE_NUM_MAP[msg.candidate_zone] || 0,
    candidate_count: msg.candidate_count,
    incoming_scanner_num: SCANNER_NUM_MAP[msg.scanner_id] || 0,
    incoming_rssi: parseInt(msg.rssi),
    age_scan_01_s: ageSeconds(msg.ts_scan_01),
    age_scan_02_s: ageSeconds(msg.ts_scan_02),
    age_scan_03_s: ageSeconds(msg.ts_scan_03),
    ts_scan_01: msg.ts_scan_01,
    ts_scan_02: msg.ts_scan_02,
    ts_scan_03: msg.ts_scan_03
};
return {msg: tsPayload, metadata: metadata, msgType: "POST_TELEMETRY_REQUEST"};

